/** Glossary terms — definition blocks + DefinedTerm JSON-LD. */
import { type Locale } from '../lib/i18n';

export interface GlossaryTerm {
  term: string;
  zh?: string;
  category: 'education' | 'visas' | 'exams' | 'travel' | 'trade';
  definition: string;
}

const GLOSSARY_EN: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: 'The Chinese Government Scholarship, administered by the China Scholarship Council. Full-coverage awards include tuition, on-campus accommodation, medical insurance and a monthly stipend; partial awards cover subsets. Applied for via Type A (government channel) or Type B (direct to a CSC-designated university).' },
  { term: 'JW202 Form', category: 'visas', definition: 'The Visa Application for Study form issued by a Chinese university to admitted self-funded and most university-scholarship international students, paired with the Admission Notice. Students on government-channel (CSC Type A) scholarships usually receive the equivalent JW201 form instead — use whichever form your university issues. Both anchor the X1 student visa application at a Chinese embassy or consulate.' },
  { term: 'Admission Notice', category: 'education', definition: 'The formal offer letter from a Chinese university confirming your place, programme and dates. Together with the JW202 form it anchors your student visa application.' },
  { term: 'X1 Visa', category: 'visas', definition: 'The Chinese student visa for programmes longer than 180 days. Issued for entry only — holders must convert it to a Residence Permit at a local Public Security Bureau within 30 days of arrival.' },
  { term: 'X2 Visa', category: 'visas', definition: 'The Chinese student visa for programmes of 180 days or less (short courses, exchange semesters). It cannot be converted to a residence permit and covers single or double entry.' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: 'China’s standardised Chinese proficiency test (Hanyu Shuiping Kaoshi), levels 1–6 in the widely used 2.0 system, with the newer 3.0 standard expanding bands. HSK 4 is the common threshold for MBBS clinical rotations; degree programmes taught in Chinese usually require HSK 5.' },
  { term: 'HSKK', category: 'exams', definition: 'The speaking companion to the HSK, tested at beginner, intermediate and advanced levels. Some Chinese-taught programmes ask for HSKK alongside the written HSK.' },
  { term: 'MOE-listed University', category: 'education', definition: 'A university approved by China’s Ministry of Education to enrol international students — and for MBBS, to teach the degree in English. If a medical school is not on the annual MOE list, avoid it.' },
  { term: 'FMGE / NExT', category: 'education', definition: 'India’s Foreign Medical Graduate Examination — the licensing test Indians must pass after an MBBS abroad to practise in India. It is being transitioned into the National Exit Test (NExT). Check current NMC rules before applying.' },
  { term: 'Residence Permit', category: 'visas', definition: 'The document that replaces your X1 visa after arrival. Issued by the local Exit-Entry Administration; required for legal long-term stay, and needed to open some bank accounts and sign leases.' },
  { term: 'Physical Examination Form', category: 'education', definition: 'The standard Chinese health check form required for X1 visas and residence permits. Must be completed at an authorised clinic; CSC scholarship applicants must use the official version shipped with the application pack.' },
  { term: 'Intake (September / March)', category: 'education', definition: 'The two main university intakes in China. September is the major one with the widest programme choice; March is a smaller intake offered by some universities for selected programmes.' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: 'The China Import and Export Fair in Guangzhou — the world’s largest trade show, held in three phases each April/May and October/November. Phase 1: electronics and machinery; Phase 2: consumer goods and home décor; Phase 3: textiles, apparel and medical products.' },
  { term: 'AQL Inspection', category: 'trade', definition: 'Acceptable Quality Level sampling — the industry-standard statistical method for inspecting production lots: a random sample is drawn and defect counts are judged against pre-agreed tolerances (critical/major/minor) before goods ship. Separately, inspections are commonly scheduled at ~20% (early build) and ~80% (near-complete) of production — those checkpoints are a workflow choice, not part of the AQL standard itself.' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: 'The carrier-issued document of title for sea freight. The “70% against B/L copy” payment term means the balance is paid when the shipping line’s document proves goods are on the water.' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: 'Wire transfer — the standard payment rail in China trade. Structured as deposit-plus-balance (commonly 30/70) rather than 100% advance, which exposes buyers to supplier default.' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: 'A bank-guaranteed payment instrument: the buyer’s bank pays the supplier when the LC’s document conditions are met. Common in established enterprise trade; costs more than TT but protects both sides.' },
  { term: 'HS Code', category: 'trade', definition: 'Harmonized System code — the international product classification that determines duty rates, restrictions and licensing for customs. Wrong HS codes are a leading cause of clearance delays and reassessed duties.' },
  { term: 'BIS Certification', category: 'trade', definition: 'Bureau of Indian Standards registration required for many electronics and goods imported into India (schemes like CRS for IT/electronics). WPC approval applies to wireless products. Both must be secured before shipment.' },
  { term: 'FCL / LCL', category: 'trade', definition: 'Full Container Load (your goods alone in a 20ft/40ft container) versus Less-than-Container-Load (your goods share container space). LCL suits trial orders; FCL wins on per-unit cost at scale.' },
  { term: 'L Visa', category: 'travel', definition: 'China’s tourist visa for private visits. Typical grant: 30–60 days per entry; some nationalities receive longer validity or multi-entry versions. Requires itinerary, bookings and onward-travel proof.' },
  { term: 'M Visa', category: 'travel', definition: 'China’s business visa for commercial activities — trade fairs, supplier meetings, contract negotiations. Usually needs an invitation letter from a Chinese company; work is prohibited on an M visa.' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: 'China’s two week-long national holidays — Chinese New Year (Jan/Feb) and National Day (1–7 October). Domestic travel surges; expect crowded sites, peak hotel prices and booked-out trains. Book months ahead or avoid.' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: 'China’s visa-free transit policy — extended from 144 to 240 hours nationwide in December 2024 — allowing nationals of many countries to enter and stay up to 10 days when transiting to a third country. Eligible nationalities, ports and conditions have expanded repeatedly; verify the current policy scope for your nationality and route before planning a trip around it.' }, // {{VERIFY}} confirm current NIA policy scope and eligible ports at publish time
];

/* zh — machine-assisted definitions, pending native-speaker review.
   Term names keep the canonical English/Chinese form (proper nouns); only
   definitions localize. Same term count and order as the en array. */
const GLOSSARY_ZH: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: '中国政府奖学金，由中国国家留学基金管理委员会（China Scholarship Council）管理。全额资助包含学费、校内住宿、医疗保险和每月津贴；部分资助覆盖其中若干项。通过 A 类（政府渠道）或 B 类（直接向 CSC 指定高校申请）。' },
  { term: 'JW202 Form', category: 'visas', definition: '由中国的大学签发给已录取的自费生及大多数校级奖学金国际学生的《来华签证申请表（JW202）》，与录取通知书配套使用。走政府渠道（CSC A 类）的奖学金生通常收到等效的 JW201 表——以你所在大学签发的表为准。两种表格都是在中国驻外使领馆申请 X1 学生签证的依据。' },
  { term: 'Admission Notice', category: 'education', definition: '中国的大学确认你的名额、专业和日期的正式录取信。它与 JW202 表一起构成学生签证申请的依据。' },
  { term: 'X1 Visa', category: 'visas', definition: '面向学习期限超过 180 天项目的中国学生签证。仅在入境时有效——持有人须在抵达后 30 天内到当地公安机关将其换发为居留许可。' },
  { term: 'X2 Visa', category: 'visas', definition: '面向学习期限不超过 180 天项目（短期课程、交换学期）的中国学生签证。不可转换为居留许可，分单次或两次入境。' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: '中国标准化的汉语水平考试（Hanyu Shuiping Kaoshi），通行 2.0 体系分 1–6 级，较新的 3.0 标准进一步扩展了等级区间。HSK 4 是 MBBS 临床轮转的常见门槛；中文授课的学位项目通常要求 HSK 5。' },
  { term: 'HSKK', category: 'exams', definition: 'HSK 的口语配套考试，分初级、中级和高级三个等级。部分中文授课项目会要求 HSKK 与笔试 HSK 一并提交。' },
  { term: 'MOE-listed University', category: 'education', definition: '经中国教育部批准招收国际学生的大学——对 MBBS 而言，还包括获准用英语授课该学位。若一所医学院不在年度教育部名单上，请避开。' },
  { term: 'FMGE / NExT', category: 'education', definition: '印度的外国医学毕业生考试（FMGE）——在国外读完 MBBS 的印度人回印度执业必须通过的执照考试。它正在过渡为国家离校考试（NExT）。申请前请核对现行 NMC 规则。' },
  { term: 'Residence Permit', category: 'visas', definition: '抵达后取代 X1 签证的证件。由当地出入境管理部门签发；合法长期居留所必需，开某些银行账户和签租约也需要它。' },
  { term: 'Physical Examination Form', category: 'education', definition: 'X1 签证和居留许可要求的标准中国体检表。必须在授权的诊所完成；CSC 奖学金申请人必须使用申请材料包自带的官方版本。' },
  { term: 'Intake (September / March)', category: 'education', definition: '中国大学的两个主要入学季。9 月是主入学季，可选专业最广；3 月是部分高校为部分项目提供的小入学季。' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: '在广州举办的中国进出口商品交易会——全球最大的贸易展会，每年 4/5 月和 10/11 月分三期举行。第一期：电子与机械；第二期：消费品与家居装饰；第三期：纺织服装与医疗产品。' },
  { term: 'AQL Inspection', category: 'trade', definition: '可接受质量水平（Acceptable Quality Level）抽检——行业标准统计抽样方法：从生产批次中随机抽样，对照事先约定的容许限度（致命/主要/次要缺陷）判定缺陷数量，合格后才发货。另外，检验通常安排在生产约 20%（早期）和约 80%（接近完工）时点——这些检查点属于工作流选择，不属于 AQL 标准本身。' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: '承运人签发的海运物权凭证。“70% 凭提单副本”这一付款条款的含义是：当船公司的单证证明货物已在途时支付尾款。' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: '电汇——中国贸易的标准支付通道。结构为“定金+尾款”（常见 30/70），而非 100% 预付——后者会让买家暴露于供应商违约风险。' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: '银行担保的支付工具：当信用证的单证条件得到满足时，买方银行向供应商付款。常见于成熟的企业贸易；比 TT 成本更高，但对双方都有保护。' },
  { term: 'HS Code', category: 'trade', definition: '协调制度（HS）编码——决定关税税率、限制和海关许可的国际产品分类。HS 编码错误是清关延误和重新核定关税的主要原因之一。' },
  { term: 'BIS Certification', category: 'trade', definition: '许多进口到印度的电子产品和商品所需的印度标准局（Bureau of Indian Standards）注册（如针对 IT/电子产品的 CRS 计划）。无线产品适用 WPC 许可。两者都必须在发货前完成。' },
  { term: 'FCL / LCL', category: 'trade', definition: '整箱装载（FCL，你的货物独占 20 尺/40 尺集装箱）与拼箱装载（LCL，你的货物与其他货物共享箱位）的对比。LCL 适合试单；达到规模后 FCL 的单件成本更优。' },
  { term: 'L Visa', category: 'travel', definition: '中国的旅游签证，用于私人访问。通常每次入境 30–60 天；部分国籍可获得更长有效期或多次入境版本。需要行程单、预订和离程交通证明。' },
  { term: 'M Visa', category: 'travel', definition: '中国的商务签证，用于商业活动——贸易展会、供应商会谈、合同谈判。通常需要中国公司的邀请函；持 M 签证禁止工作。' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: '中国两个为期一周的全国性假期——春节（1/2 月）和国庆假期（10 月 1–7 日）。国内旅行激增；预计景点拥挤、酒店价格达到峰值、火车票售罄。提前数月预订或避开。' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: '中国过境免签政策——2024 年 12 月在全国范围内从 144 小时延长至 240 小时——允许多国公民在过境前往第三国时入境并停留最多 10 天。适用国籍、口岸和条件已多次扩大；围绕它规划行程前，请核实针对你的国籍和航线的现行政策范围。' },
];

/* fr — machine-assisted definitions, pending native-speaker review. */
const GLOSSARY_FR: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: 'La bourse du gouvernement chinois, administrée par le China Scholarship Council. Les attributions complètes couvrent les frais de scolarité, le logement sur le campus, l’assurance maladie et une allocation mensuelle ; les attributions partielles couvrent des sous-ensembles. Candidature via le Type A (canal gouvernemental) ou le Type B (directement auprès d’une université désignée CSC).' },
  { term: 'JW202 Form', category: 'visas', definition: 'Le formulaire de demande de visa pour études délivré par une université chinoise aux étudiants internationaux admis autofinancés et à la plupart des boursiers universitaires, en parallèle de l’Admission Notice. Les boursiers du canal gouvernemental (CSC Type A) reçoivent généralement le formulaire équivalent JW201 — utilisez le formulaire délivré par votre université. L’un comme l’autre ancre la demande de visa étudiant X1 auprès d’une ambassade ou d’un consulat de Chine.' },
  { term: 'Admission Notice', category: 'education', definition: 'La lettre d’offre formelle d’une université chinoise confirmant votre place, votre programme et vos dates. Avec le formulaire JW202, elle ancre votre demande de visa étudiant.' },
  { term: 'X1 Visa', category: 'visas', definition: 'Le visa étudiant chinois pour les programmes de plus de 180 jours. Délivré pour l’entrée uniquement — les titulaires doivent le convertir en permis de séjour auprès d’un Bureau de la sécurité publique local dans les 30 jours suivant l’arrivée.' },
  { term: 'X2 Visa', category: 'visas', definition: 'Le visa étudiant chinois pour les programmes de 180 jours ou moins (cours courts, semestres d’échange). Il ne peut pas être converti en permis de séjour et couvre une ou deux entrées.' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: 'Le test standardisé de compétence en chinois de la Chine (Hanyu Shuiping Kaoshi), niveaux 1 à 6 dans le système 2.0 largement utilisé, la nouvelle norme 3.0 élargissant les paliers. Le HSK 4 est le seuil courant pour les rotations cliniques du MBBS ; les cursus enseignés en chinois exigent généralement le HSK 5.' },
  { term: 'HSKK', category: 'exams', definition: 'L’épreuve d’expression orale qui accompagne le HSK, testée aux niveaux débutant, intermédiaire et avancé. Certains programmes enseignés en chinois demandent le HSKK en plus du HSK écrit.' },
  { term: 'MOE-listed University', category: 'education', definition: 'Une université approuvée par le ministère de l’Éducation chinois pour inscrire des étudiants internationaux — et, pour le MBBS, pour enseigner le diplôme en anglais. Si une faculté de médecine n’est pas sur la liste annuelle du MOE, évitez-la.' },
  { term: 'FMGE / NExT', category: 'education', definition: 'L’examen des diplômés médicaux étrangers en Inde — le test de licence que les Indiens doivent réussir après un MBBS à l’étranger pour exercer en Inde. Il est en cours de transition vers le National Exit Test (NExT). Vérifiez les règles NMC actuelles avant de candidater.' },
  { term: 'Residence Permit', category: 'visas', definition: 'Le document qui remplace votre visa X1 après l’arrivée. Délivré par l’administration Exit-Entry locale ; requis pour un séjour légal de longue durée, et nécessaire pour ouvrir certains comptes bancaires et signer des baux.' },
  { term: 'Physical Examination Form', category: 'education', definition: 'Le formulaire standard de contrôle de santé chinois requis pour les visas X1 et les permis de séjour. À compléter dans une clinique agréée ; les candidats à la bourse CSC doivent utiliser la version officielle fournie dans le dossier de candidature.' },
  { term: 'Intake (September / March)', category: 'education', definition: 'Les deux principales rentrées universitaires en Chine. Septembre est la majeure, avec le choix de programmes le plus large ; mars est une rentrée plus réduite proposée par certaines universités pour des programmes sélectionnés.' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: 'La Foire chinoise de l’import et de l’export à Canton — le plus grand salon commercial du monde, en trois phases chaque avril/mai et octobre/novembre. Phase 1 : électronique et machines ; Phase 2 : biens de consommation et décoration ; Phase 3 : textiles, habillement et produits médicaux.' },
  { term: 'AQL Inspection', category: 'trade', definition: 'L’échantillonnage par niveau de qualité acceptable (Acceptable Quality Level) — la méthode statistique standard du secteur pour inspecter les lots : un échantillon aléatoire est tiré et le nombre de défauts est jugé contre des tolérances convenues à l’avance (critique/majeur/mineur) avant l’expédition. Par ailleurs, les inspections sont couramment programmées à ~20 % (début de production) et ~80 % (presque terminée) — ces points de contrôle relèvent d’un choix de workflow, non de la norme AQL elle-même.' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: 'Le document de titre délivré par le transporteur pour le fret maritime. Le terme de paiement « 70 % contre copie du B/L » signifie que le solde est payé quand le document de la compagnie maritime prouve que les marchandises sont sur l’eau.' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: 'Le virement télégraphique — le rail de paiement standard du commerce avec la Chine. Structuré en acompte plus solde (généralement 30/70) plutôt qu’en 100 % d’avance, qui expose l’acheteur au défaut du fournisseur.' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: 'Un instrument de paiement garanti par une banque : la banque de l’acheteur paie le fournisseur lorsque les conditions documentaires du LC sont remplies. Courant dans le commerce d’entreprise établi ; coûte plus que le TT mais protège les deux parties.' },
  { term: 'HS Code', category: 'trade', definition: 'Le code du Système harmonisé — la classification internationale des produits qui détermine droits de douane, restrictions et licences. Un mauvais code HS est une cause majeure de retards de dédouanement et de droits réévalués.' },
  { term: 'BIS Certification', category: 'trade', definition: 'L’enregistrement auprès du Bureau of Indian Standards requis pour beaucoup d’électronique et de biens importés en Inde (schémas comme le CRS pour l’informatique/électronique). L’approbation WPC s’applique aux produits sans fil. Les deux doivent être sécurisés avant l’expédition.' },
  { term: 'FCL / LCL', category: 'trade', definition: 'Full Container Load (vos marchandises seules dans un conteneur 20/40 pieds) contre Less-than-Container-Load (vos marchandises partagent l’espace du conteneur). Le LCL convient aux commandes d’essai ; le FCL gagne en coût unitaire à l’échelle.' },
  { term: 'L Visa', category: 'travel', definition: 'Le visa touristique chinois pour les visites privées. Octroi typique : 30–60 jours par entrée ; certaines nationalités reçoivent des validités plus longues ou des versions multi-entrées. Exige itinéraire, réservations et preuve de continuation.' },
  { term: 'M Visa', category: 'travel', definition: 'Le visa d’affaires chinois pour les activités commerciales — salons, réunions fournisseurs, négociations de contrats. Nécessite généralement une lettre d’invitation d’une entreprise chinoise ; le travail est interdit avec un visa M.' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: 'Les deux semaines de congés nationales chinoises — Nouvel An chinois (janv./févr.) et Fête nationale (1–7 octobre). Le tourisme intérieur s’emballe ; attendez-vous à des sites bondés, des prix d’hôtel au pic et des trains complets. Réservez des mois à l’avance ou évitez.' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: 'La politique de transit sans visa de la Chine — étendue de 144 à 240 heures à l’échelle nationale en décembre 2024 — permettant aux ressortissants de nombreux pays d’entrer et de rester jusqu’à 10 jours en transit vers un pays tiers. Les nationalités, ports et conditions éligibles ont été élargis à plusieurs reprises ; vérifiez la portée actuelle de la politique pour votre nationalité et votre itinéraire avant de planifier un voyage autour.' },
];

/* ar — machine-assisted definitions, pending native-speaker review. */
const GLOSSARY_AR: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: 'المنحة الحكومية الصينية، تديرها لجنة منح الدراسة الصينية (China Scholarship Council). الجوائز الكاملة تشمل الرسوم الدراسية والسكن الجامعي والتأمين الصحي وراتبًا شهريًا؛ والجوائز الجزئية تغطي بعض هذه البنود. تُقدَّم عبر النوع A (القناة الحكومية) أو النوع B (مباشرة إلى جامعة معتمدة من CSC).' },
  { term: 'JW202 Form', category: 'visas', definition: 'نموذج طلب تأشيرة الدراسة الذي تُصدره جامعة صينية للطلاب الدوليين المقبولين الممولين ذاتيًا ومعظم حاملي منح الجامعات، مقترنًا بخطاب القبول. طلاب القناة الحكومية (CSC النوع A) يتلقون عادةً نموذج JW201 المكافئ — استخدم النموذج الذي تُصدره جامعتك. كلاهما أساس طلب تأشيرة الطالب X1 لدى سفارة أو قنصلية صينية.' },
  { term: 'Admission Notice', category: 'education', definition: 'خطاب القبول الرسمي من جامعة صينية يؤكد مقعدك وبرنامجك وتواريخك. وهو مع نموذج JW202 أساس طلب تأشيرة الطالب.' },
  { term: 'X1 Visa', category: 'visas', definition: 'تأشيرة الطالب الصينية للبرامج الأطول من 180 يومًا. تُصدر للدخول فقط — على حامليها تحويلها إلى تصريح إقامة لدى مكتب الأمن العام المحلي خلال 30 يومًا من الوصول.' },
  { term: 'X2 Visa', category: 'visas', definition: 'تأشيرة الطالب الصينية للبرامج التي تصل مدتها إلى 180 يومًا أو أقل (دورات قصيرة، فصول تبادلي). لا يمكن تحويلها إلى تصريح إقامة، وتغطي دخولًا واحدًا أو مزدوجًا.' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: 'اختبار إتقان اللغة الصينية المعياري في الصين (Hanyu Shuiping Kaoshi)، بمستويات 1–6 في نظام 2.0 الشائع، مع معيار 3.0 الأحدث الذي يوسّع الفئات. HSK 4 هو الحد الشائع للتدريبات السريرية في MBBS؛ والبرامج الجامعية المدرّسة بالصينية تتطلب عادةً HSK 5.' },
  { term: 'HSKK', category: 'exams', definition: 'اختبار التحدث المرافق لاختبار HSK، ويُختبر بمستويات مبتدئ ومتوسط ومتقدم. بعض البرامج المدرّسة بالصينية تطلب HSKK إلى جانب HSK الكتابي.' },
  { term: 'MOE-listed University', category: 'education', definition: 'جامعة معتمدة من وزارة التعليم الصينية لقبول الطلاب الدوليين — ولـMBBS، لتدريس الدرجة بالإنجليزية. إذا لم تكن كلية الطب على قائمة MOE السنوية فتجنّبها.' },
  { term: 'FMGE / NExT', category: 'education', definition: 'امتحان الخريجين الطبيين الأجانب في الهند — اختبار الترخيص الذي على الهنود اجتيازه بعد MBBS في الخارج للممارسة في الهند. وهو يتحول إلى اختبار الخروج الوطني (NExT). تحقق من قواعد NMC الحالية قبل التقديم.' },
  { term: 'Residence Permit', category: 'visas', definition: 'المستند الذي يحل محل تأشيرة X1 بعد الوصول. تصدره إدارة الخروج والدخول المحلية؛ وهو مطلوب للإقامة الطويلة القانونية، ولفتح بعض الحسابات البنكية وتوقيع عقود الإيجار.' },
  { term: 'Physical Examination Form', category: 'education', definition: 'نموذج الفحص الصحي الصيني القياسي المطلوب لتأشيرات X1 وتصاريح الإقامة. يجب إتمامه في عيادة مرخّصة؛ ومتقدمو منحة CSC يجب أن يستخدموا النسخة الرسمية المرفقة بحزمة التقديم.' },
  { term: 'Intake (September / March)', category: 'education', definition: 'موعدا الالتحاق الرئيسيان في الجامعات الصينية. سبتمبر هو الأكبر بخيار البرامج الأوسع؛ ومارس دفعة أصغر تقدمها بعض الجامعات لبرامج مختارة.' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: 'معرض الصين للاستيراد والتصدير في قوانغتشو — أكبر معرض تجاري في العالم، يُقام على ثلاث مراحل كل أبريل/مايو وأكتوبر/نوفمبر. المرحلة 1: إلكترونيات وآلات؛ المرحلة 2: سلع استهلاكية وديكور منزلي؛ المرحلة 3: منسوجات وملابس ومنتجات طبية.' },
  { term: 'AQL Inspection', category: 'trade', definition: 'أخذ العينات بمستوى الجودة المقبول (Acceptable Quality Level) — الطريقة الإحصائية المعيارية في الصناعة لفحص دفعات الإنتاج: تُسحب عينة عشوائية ويُحكم على أعداد العيوب مقابل هوامش متفق عليها مسبقًا (حرج/رئيسي/ثانوي) قبل شحن البضاعة. وبصورة منفصلة، تُبرمج الفحوص عادةً عند نحو 20% (بناء مبكر) ونحو 80% (قرب الاكتمال) من الإنتاج — تلك النقاط خيار سير عمل وليست جزءًا من معيار AQL نفسه.' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: 'مستند الملكية الذي يصدره الناقل للشحن البحري. مصطلح الدفع «70% مقابل نسخة بوليصة الشحن» يعني أن الرصيد يُدفع عندما تثبت وثيقة شركة الملاحة أن البضاعة على الماء.' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: 'التحويل البرقي — قناة الدفع القياسية في تجارة الصين. يُهيكل عربونًا مع رصيد (شائع 30/70) بدلًا من 100% مقدمة، التي تعرّض المشتري لتعثّر المورد.' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: 'أداة دفع مضمونة من بنك: يدفع بنك المشتري للمورد عند استيفاء الشروط المستندية في الاعتماد. شائع في تجارة الشركات الراسخة؛ يكلّف أكثر من TT لكنه يحمي الطرفين.' },
  { term: 'HS Code', category: 'trade', definition: 'رمز النظام المنسق — تصنيف المنتجات الدولي الذي يحدد أعباء الجمارك والقيود والتراخيص. رموز HS الخاطئة سبب رئيسي لتأخيرات التخليص وإعادة تقييم الرسوم.' },
  { term: 'BIS Certification', category: 'trade', definition: 'تسجيل مكتب المعايير الهندية المطلوب لكثير من الإلكترونيات والسلع المستوردة إلى الهند (خطط مثل CRS للتقنية/الإلكترونيات). وتنطبق موافقة WPC على المنتجات اللاسلكية. كلاهما يجب تأمينه قبل الشحن.' },
  { term: 'FCL / LCL', category: 'trade', definition: 'حاوية كاملة (بضاعتك وحدك في حاوية 20/40 قدمًا) مقابل أقل من حاوية (بضاعتك تشارك المساحة). LCL يناسب الطلبات التجريبية؛ وFCL يتفوق في تكلفة الوحدة عند الحجم.' },
  { term: 'L Visa', category: 'travel', definition: 'تأشيرة السياحة الصينية للزيارات الخاصة. المنح المعتاد: 30–60 يومًا لكل دخول؛ وبعض الجنسيات تحصل على صلاحية أطول أو نسخ متعددة الدخول. تتطلب برنامج رحلة وحجوزات وإثبات سفر لاحق.' },
  { term: 'M Visa', category: 'travel', definition: 'تأشيرة الأعمال الصينية للأنشطة التجارية — المعارض واجتماعات الموردين ومفاوضات العقود. تحتاج عادةً خطاب دعوة من شركة صينية؛ والعمل ممنوع على تأشيرة M.' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: 'عطلتا الصين الوطنيتان اللتان تدومان أسبوعًا — رأس السنة الصينية (يناير/فبراير) والعيد الوطني (1–7 أكتوبر). يشتد السفر الداخلي؛ توقع مواقع مزدحمة وأسعار فنادق في القمة وقطارات محجوزة بالكامل. احجز قبل أشهر أو تجنّبها.' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: 'سياسة العبور بدون تأشيرة في الصين — الممتدة من 144 إلى 240 ساعة على مستوى البلاد في ديسمبر 2024 — وتتيح لمواطني دول كثيرة الدخول والبقاء حتى 10 أيام عند العبور إلى بلد ثالث. الجنسيات والموانئ والشروط المؤهلة توسّعت مرارًا؛ تحقق من نطاق السياسة الحالي لجنسيتك ومسارك قبل التخطيط لرحلة تعتمد عليها.' },
];

/* es — machine-assisted definitions, pending native-speaker review. */
const GLOSSARY_ES: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: 'La beca del gobierno chino, administrada por el China Scholarship Council. Las concesiones completas incluyen matrícula, alojamiento en el campus, seguro médico y una asignación mensual; las parciales cubren subconjuntos. Se solicita vía Tipo A (canal gubernamental) o Tipo B (directamente a una universidad designada por CSC).' },
  { term: 'JW202 Form', category: 'visas', definition: 'El formulario de solicitud de visado de estudios que emite una universidad china a los estudiantes internacionales admitidos autofinanciados y a la mayoría de becarios universitarios, junto con la Admission Notice. Los becarios del canal gubernamental (CSC Tipo A) suelen recibir el formulario equivalente JW201 — usa el formulario que emita tu universidad. Ambos anclan la solicitud del visado de estudiante X1 ante una embajada o consulado de China.' },
  { term: 'Admission Notice', category: 'education', definition: 'La carta de oferta formal de una universidad china que confirma tu plaza, programa y fechas. Junto con el formulario JW202, ancla tu solicitud de visado de estudiante.' },
  { term: 'X1 Visa', category: 'visas', definition: 'El visado de estudiante chino para programas de más de 180 días. Se emite solo para la entrada — los titulares deben convertirlo en un permiso de residencia en una Oficina de Seguridad Pública local dentro de los 30 días posteriores a la llegada.' },
  { term: 'X2 Visa', category: 'visas', definition: 'El visado de estudiante chino para programas de 180 días o menos (cursos cortos, semestres de intercambio). No puede convertirse en permiso de residencia y cubre una o dos entradas.' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: 'El test estandarizado de competencia en chino de China (Hanyu Shuiping Kaoshi), niveles 1–6 en el sistema 2.0 de uso generalizado, con la nueva norma 3.0 que amplía las bandas. HSK 4 es el umbral común para las rotaciones clínicas del MBBS; los programas de grado impartidos en chino suelen exigir HSK 5.' },
  { term: 'HSKK', category: 'exams', definition: 'La prueba de expresión oral que acompaña al HSK, evaluada en niveles básico, intermedio y avanzado. Algunos programas impartidos en chino piden HSKK junto con el HSK escrito.' },
  { term: 'MOE-listed University', category: 'education', definition: 'Una universidad aprobada por el Ministerio de Educación de China para matricular estudiantes internacionales — y, para el MBBS, para impartir el título en inglés. Si una facultad de medicina no está en la lista anual del MOE, evítala.' },
  { term: 'FMGE / NExT', category: 'education', definition: 'El examen de graduados médicos extranjeros de India — la prueba de licencia que los indios deben aprobar tras un MBBS en el extranjero para ejercer en India. Está en transición hacia el National Exit Test (NExT). Consulta las reglas actuales del NMC antes de solicitar.' },
  { term: 'Residence Permit', category: 'visas', definition: 'El documento que sustituye a tu visado X1 tras la llegada. Lo emite la administración local de Salida-Entrada; es necesario para la estancia legal de largo plazo, y para abrir algunas cuentas bancarias y firmar contratos de alquiler.' },
  { term: 'Physical Examination Form', category: 'education', definition: 'El formulario estándar de chequeo de salud chino requerido para visados X1 y permisos de residencia. Debe completarse en una clínica autorizada; los solicitantes de la beca CSC deben usar la versión oficial incluida en el paquete de solicitud.' },
  { term: 'Intake (September / March)', category: 'education', definition: 'Las dos principales entradas universitarias en China. Septiembre es la grande, con la oferta de programas más amplia; marzo es una entrada menor que ofrecen algunas universidades para programas seleccionados.' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: 'La Feria de Importación y Exportación de China en Cantón — la mayor feria comercial del mundo, celebrada en tres fases cada abril/mayo y octubre/noviembre. Fase 1: electrónica y maquinaria; Fase 2: bienes de consumo y decoración del hogar; Fase 3: textiles, confección y productos médicos.' },
  { term: 'AQL Inspection', category: 'trade', definition: 'Muestreo por Nivel de Calidad Aceptable (Acceptable Quality Level) — el método estadístico estándar de la industria para inspeccionar lotes: se extrae una muestra aleatoria y los defectos se juzgan contra tolerancias acordadas previamente (crítico/mayor/menor) antes de embarcar. Aparte, las inspecciones suelen programarse al ~20% (producción temprana) y ~80% (casi completa) — esos puntos de control son una elección de flujo de trabajo, no parte de la norma AQL en sí.' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: 'El documento de título emitido por el transportista para el flete marítimo. El término de pago «70% contra copia del B/L» significa que el saldo se paga cuando el documento de la naviera prueba que la mercancía está en el agua.' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: 'La transferencia telegráfica — el raíl de pago estándar en el comercio con China. Estructurada como anticipo más saldo (comúnmente 30/70) en lugar de 100% por adelantado, que expone al comprador al incumplimiento del proveedor.' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: 'Un instrumento de pago garantizado por un banco: el banco del comprador paga al proveedor cuando se cumplen las condiciones documentales del LC. Común en el comercio empresarial consolidado; cuesta más que el TT pero protege a ambas partes.' },
  { term: 'HS Code', category: 'trade', definition: 'Código del Sistema Armonizado — la clasificación internacional de productos que determina aranceles, restricciones y licencias aduaneras. Los códigos HS erróneos son una causa principal de retrasos en el despacho y de aranceles reevaluados.' },
  { term: 'BIS Certification', category: 'trade', definition: 'El registro ante la Oficina de Normas de India (Bureau of Indian Standards) requerido para muchos electrónicos y bienes importados a India (esquemas como el CRS para IT/electrónica). La aprobación WPC aplica a productos inalámbricos. Ambos deben asegurarse antes del embarque.' },
  { term: 'FCL / LCL', category: 'trade', definition: 'Full Container Load (tu mercancía sola en un contenedor de 20/40 pies) frente a Less-than-Container-Load (tu mercancía comparte espacio de contenedor). El LCL sirve para pedidos de prueba; el FCL gana en costo por unidad a escala.' },
  { term: 'L Visa', category: 'travel', definition: 'El visado de turista de China para visitas privadas. Concesión típica: 30–60 días por entrada; algunas nacionalidades reciben valideces más largas o versiones multientrada. Requiere itinerario, reservas y prueba de continuación del viaje.' },
  { term: 'M Visa', category: 'travel', definition: 'El visado de negocios de China para actividades comerciales — ferias, reuniones con proveedores, negociación de contratos. Normalmente necesita una carta de invitación de una empresa china; el trabajo está prohibido con un visado M.' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: 'Los dos festivos nacionales de una semana en China — Año Nuevo chino (enero/febrero) y Día Nacional (1–7 de octubre). El turismo interno se dispara; espera sitios abarrotados, precios hoteleros en máximos y trenes agotados. Reserva con meses de antelación o evítalo.' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: 'La política de tránsito sin visado de China — ampliada de 144 a 240 horas en todo el país en diciembre de 2024 — que permite a nacionales de muchos países entrar y quedarse hasta 10 días cuando están en tránsito hacia un tercer país. Las nacionalidades, puertos y condiciones elegibles se han ampliado repetidamente; verifica el alcance actual de la política para tu nacionalidad y ruta antes de planificar un viaje en torno a ella.' },
];

/* de — machine-assisted definitions, pending native-speaker review. */
const GLOSSARY_DE: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: 'Das chinesische Regierungsstipendium, verwaltet vom China Scholarship Council. Vollständige Zuwendungen umfassen Studiengebühren, Unterkunft auf dem Campus, Krankenversicherung und eine monatliche Zuwendung; teilweise Zuwendungen decken Teilbereiche ab. Bewerbung über Typ A (Regierungskanal) oder Typ B (direkt bei einer CSC-designierten Universität).' },
  { term: 'JW202 Form', category: 'visas', definition: 'Das Formular „Visa Application for Study“, das eine chinesische Universität zugelassenen, selbstfinanzierten internationalen Studierenden und den meisten Universitätsstipendiaten ausstellt, zusammen mit dem Admission Notice. Studierende im Regierungskanal (CSC Typ A) erhalten in der Regel stattdessen das gleichwertige Formular JW201 — verwenden Sie das Formular, das Ihre Universität ausstellt. Beide bilden die Grundlage des X1-Studentenvisumantrags bei einer chinesischen Botschaft oder einem Konsulat.' },
  { term: 'Admission Notice', category: 'education', definition: 'Das offizielle Zulassungsschreiben einer chinesischen Universität, das Ihren Studienplatz, Ihr Programm und Ihre Termine bestätigt. Zusammen mit dem JW202-Formular bildet es die Grundlage Ihres Studentenvisumantrags.' },
  { term: 'X1 Visa', category: 'visas', definition: 'Das chinesische Studentenvisum für Programme länger als 180 Tage. Es wird nur für die Einreise ausgestellt — Inhaber müssen es innerhalb von 30 Tagen nach Ankunft bei einer örtlichen Behörde für öffentliche Sicherheit in eine Aufenthaltserlaubnis umwandeln.' },
  { term: 'X2 Visa', category: 'visas', definition: 'Das chinesische Studentenvisum für Programme von 180 Tagen oder weniger (Kurzkurse, Austauschsemester). Es kann nicht in eine Aufenthaltserlaubnis umgewandelt werden und gilt für ein- oder zweimalige Einreise.' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: 'Chinas standardisierter Chinesisch-Sprachtest (Hanyu Shuiping Kaoshi), Stufen 1–6 im verbreiteten 2.0-System, wobei der neuere 3.0-Standard die Bänder erweitert. HSK 4 ist die übliche Schwelle für klinische MBBS-Rotationen; chinesischsprachige Studiengänge verlangen meist HSK 5.' },
  { term: 'HSKK', category: 'exams', definition: 'Die mündliche Ergänzungsprüfung zum HSK, getestet auf Grund-, Mittel- und Oberstufe. Manche chinesischsprachige Programme verlangen die HSKK zusätzlich zum schriftlichen HSK.' },
  { term: 'MOE-listed University', category: 'education', definition: 'Eine vom chinesischen Bildungsministerium genehmigte Universität zur Einschreibung internationaler Studierender — und im Fall des MBBS zur englischsprachigen Lehre des Abschlusses. Ist eine medizinische Hochschule nicht auf der jährlichen MOE-Liste, meiden Sie sie.' },
  { term: 'FMGE / NExT', category: 'education', definition: 'Indiens Foreign Medical Graduate Examination — die Lizenzprüfung, die Inder nach einem MBBS im Ausland bestehen müssen, um in Indien zu praktizieren. Sie wird in den National Exit Test (NExT) überführt. Prüfen Sie die aktuellen NMC-Regeln, bevor Sie sich bewerben.' },
  { term: 'Residence Permit', category: 'visas', definition: 'Das Dokument, das Ihr X1-Visum nach der Ankunft ersetzt. Ausgestellt von der örtlichen Exit-Entry-Verwaltung; erforderlich für den legalen Langzeitaufenthalt und nötig für manche Bankkonten und Mietverträge.' },
  { term: 'Physical Examination Form', category: 'education', definition: 'Das Standardformular der chinesischen Gesundheitsuntersuchung, das für X1-Visa und Aufenthaltserlaubnisse verlangt wird. Muss in einer autorisierten Klinik ausgefüllt werden; CSC-Stipendienbewerber müssen die offizielle Version aus dem Bewerbungspaket verwenden.' },
  { term: 'Intake (September / March)', category: 'education', definition: 'Die beiden wichtigsten Studienbeginn-Termine in China. September ist der große mit der breitesten Programmwahl; März ist ein kleinerer Termin, den manche Universitäten für ausgewählte Programme anbieten.' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: 'Die China Import and Export Fair in Guangzhou — die größte Handelsmesse der Welt, in drei Phasen jeweils im April/Mai und Oktober/November. Phase 1: Elektronik und Maschinen; Phase 2: Konsumgüter und Wohndekoration; Phase 3: Textilien, Bekleidung und Medizinprodukte.' },
  { term: 'AQL Inspection', category: 'trade', definition: 'Acceptable-Quality-Level-Stichproben — die branchenübliche statistische Methode zur Prüfung von Produktionslosen: Eine Zufallsstichprobe wird gezogen und die Fehlerzahl an vorab vereinbarten Toleranzen (kritisch/maior/minor) gemessen, bevor die Ware versandt wird. Unabhängig davon werden Inspektionen üblicherweise bei ca. 20 % (frühe Fertigung) und ca. 80 % (nahezu abgeschlossen) der Produktion angesetzt — diese Kontrollpunkte sind eine Workflow-Entscheidung, kein Teil des AQL-Standards selbst.' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: 'Das vom Frachtführer ausgestellte Traditionspapier für Seefracht. Die Zahlungsbedingung „70 % gegen B/L-Kopie“ bedeutet, dass der Restbetrag gezahlt wird, wenn das Dokument der Reederei belegt, dass die Ware unterwegs ist.' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: 'Überweisung — die Standardzahlungsroute im China-Handel. Strukturiert als Anzahlung plus Restbetrag (üblich 30/70) statt 100 % Vorauszahlung, die den Käufer dem Ausfallrisiko des Lieferanten aussetzt.' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: 'Ein bankgarantiertes Zahlungsinstrument: Die Bank des Käufers zahlt an den Lieferanten, wenn die dokumentaren Bedingungen des LC erfüllt sind. Im etablierten Unternehmenshandel üblich; teurer als TT, schützt aber beide Seiten.' },
  { term: 'HS Code', category: 'trade', definition: 'Harmonized-System-Code — die internationale Produktklassifikation, die Zollsätze, Beschränkungen und Lizenzierungen für den Zoll bestimmt. Falsche HS-Codes sind eine Hauptursache für Abfertigungsverzögerungen und neu festgesetzte Zölle.' },
  { term: 'BIS Certification', category: 'trade', definition: 'Die Registrierung beim Bureau of Indian Standards, die für viele nach Indien importierte Elektronik und Waren verlangt wird (Regelwerke wie CRS für IT/Elektronik). Die WPC-Zulassung gilt für Funkprodukte. Beide müssen vor dem Versand gesichert sein.' },
  { term: 'FCL / LCL', category: 'trade', definition: 'Full Container Load (Ihre Ware allein im 20-/40-Fuß-Container) versus Less-than-Container-Load (Ihre Ware teilt sich den Containerplatz). LCL passt zu Probeaufträgen; FCL gewinnt bei Skalierung die Stückkostenrechnung.' },
  { term: 'L Visa', category: 'travel', definition: 'Chinas Touristenvisum für private Besuche. Übliche Erteilung: 30–60 Tage pro Einreise; manche Nationalitäten erhalten längere Gültigkeit oder Mehrfacheinreise. Verlangt Reiseroute, Buchungen und Weiterreisenachweis.' },
  { term: 'M Visa', category: 'travel', definition: 'Chinas Geschäftsvisum für kommerzielle Aktivitäten — Messen, Lieferantentreffen, Vertragsverhandlungen. Braucht üblicherweise ein Einladungsschreiben eines chinesischen Unternehmens; Arbeit ist mit M-Visum verboten.' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: 'Chinas zwei einwöchige nationale Feiertage — Chinesisches Neujahrsfest (Jan./Feb.) und Nationalfeiertag (1.–7. Oktober). Der Binnenreiseverkehr explodiert; rechnen Sie mit vollen Sehenswürdigkeiten, Höchstpreisen bei Hotels und ausgebuchten Zügen. Monate im Voraus buchen oder meiden.' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: 'Chinas visumfreie Transitregelung — im Dezember 2024 landesweit von 144 auf 240 Stunden ausgedehnt — die Staatsangehörigen vieler Länder die Einreise und einen Aufenthalt von bis zu 10 Tagen beim Transit in ein Drittland erlaubt. Zugelassene Nationalitäten, Häfen und Bedingungen wurden wiederholt erweitert; prüfen Sie den aktuellen Regelungsumfang für Ihre Nationalität und Route, bevor Sie eine Reise darauf aufbauen.' }, // {{VERIFY}} confirm current NIA policy scope and eligible ports at publish time
];

/* ja — machine-assisted definitions, pending native-speaker review. */
const GLOSSARY_JA: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: '中国政府奨学金。中国国家留学基金管理委员会（China Scholarship Council）が運営します。全額支給は学費、校内宿舎、医療保険、毎月の手当を含み、部分支給はその一部をカバーします。A類（政府ルート）またはB類（CSC指定大学への直接出願）で応募します。' },
  { term: 'JW202 Form', category: 'visas', definition: '中国の大学が、合格した自己資金の留学生および大学奨学生の多くに発行する「留学ビザ申請表（JW202）」。Admission Notice（入学通知書）と併せて使われます。政府ルート（CSC A類）の奨学生は通常、同等のJW201を受け取ります——大学が発行する書類を使用してください。いずれも中国大使館・領事館でのX1学生ビザ申請の根拠となります。' },
  { term: 'Admission Notice', category: 'education', definition: '中国の大学が、あなたの枠、プログラム、日程を確認する正式な合格通知書。JW202表とともに学生ビザ申請の根拠となります。' },
  { term: 'X1 Visa', category: 'visas', definition: '180日を超えるプログラム向けの中国学生ビザ。入国時のみ有効——到着後30日以内に現地の公安局で居留許可に切り替える必要があります。' },
  { term: 'X2 Visa', category: 'visas', definition: '180日以内のプログラム（短期コース、交換学期）向けの中国学生ビザ。居留許可への変更はできず、1回または2回の入国をカバーします。' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: '中国の標準化された中国語能力試験（漢語水平考試/Hanyu Shuiping Kaoshi）。広く使われる2.0体系では1～6級、新しい3.0基準では等級がさらに拡張されます。HSK 4はMBBS臨床実習の一般的な基準で、中国語で行う学位プログラムは通常HSK 5を要求します。' },
  { term: 'HSKK', category: 'exams', definition: 'HSKのスピーキング版で、初級・中級・上級の3段階で実施されます。中国語授業の一部プログラムは、筆記HSKとともにHSKKを求めます。' },
  { term: 'MOE-listed University', category: 'education', definition: '中国教育部が国際学生の受け入れ——MBBSの場合は英語での学位教育——を承認した大学。医科大学が年度のMOEリストに載っていない場合は避けてください。' },
  { term: 'FMGE / NExT', category: 'education', definition: 'インドの外国人医学卒業生試験（FMGE）——海外でMBBSを修めたインド人がインドで開業するために合格しなければならない資格試験。現在はNational Exit Test（NExT）への移行中です。出願前に現行のNMC規則を確認してください。' },
  { term: 'Residence Permit', category: 'visas', definition: '到着後にX1ビザに代わる書類。現地の出入境管理局が発行し、合法的な長期滞在に必須で、一部の銀行口座開設や賃貸契約にも必要です。' },
  { term: 'Physical Examination Form', category: 'education', definition: 'X1ビザと居留許可に必要な中国の標準健康診断書。指定クリニックで受診しなければならず、CSC奨学金の出願者は申請パッケージ同梱の公式版を使う必要があります。' },
  { term: 'Intake (September / March)', category: 'education', definition: '中国の大学の2つの主要入学時期。9月が最大で、選べるプログラムが最も広い。3月は一部の大学が一部のプログラムで設けている小規模な入学時期です。' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: '広州で開かれる中国輸出入商品交易会（広交会）——世界最大の貿易見本市で、毎年4～5月と10～11月に3期に分けて開催されます。第1期：電子・機械。第2期：消費財・インテリア。第3期：繊維・アパレル・医療製品。' },
  { term: 'AQL Inspection', category: 'trade', definition: 'AQL（Acceptable Quality Level）抜き取り検査——生産ロットを検査する業界標準の統計手法：無作為にサンプルを抽出し、事前に合意した許容限度（致命的/重大/軽微）に対して欠陥数を判定してから出荷します。別途、検査は生産の約20%（初期）と約80%（ほぼ完成）の時点で実施されるのが一般的——これらのチェックポイントはワークフローの選択であり、AQL規格自体の一部ではありません。' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: '海運で船会社が発行する有価証券的な書類（船荷証券）。「B/Lコピー受け取りで70%」という支払条件は、船会社の書類が積み出しを証明した時点で残額を支払うことを意味します。' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: '電信送金（TT）——中国貿易の標準的な決済手段。手付金＋残額（一般的に30/70）の構成で、100%前払い——仕入れ先の不履行リスクを買う形——は避けます。' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: '銀行が支払いを保証する手段：LC（信用状）の書類条件が満たされると、買主の銀行がサプライヤーへ支払います。成熟した法人取引で一般的。TTより費用がかかりますが双方を保護します。' },
  { term: 'HS Code', category: 'trade', definition: 'HSコード（調和システム）——関税率、規制、通関ライセンスを決める国際的な製品分類。HSコードの誤りは、通関遅延や関税再査定の主な原因です。' },
  { term: 'BIS Certification', category: 'trade', definition: 'インドに輸入される多くの電子機器・商品に必要なインド標準局（Bureau of Indian Standards）登録（IT/電子機器向けCRSなど）。無線製品にはWPC認可が適用されます。いずれも出荷前に取得が必要です。' },
  { term: 'FCL / LCL', category: 'trade', definition: 'FCL（Full Container Load、20/40フィートコンテナを占有）とLCL（Less-than-Container-Load、スペースを共有）の対比。LCLはテスト発注に向き、規模が大きくなるとFCLの方が単位あたりコストで有利になります。' },
  { term: 'L Visa', category: 'travel', definition: '中国の個人旅行向け観光ビザ。通常の付与は1回の入国につき30～60日；国籍によってはより長い有効期間や複数入国版が発行されます。旅程表、予約、帰路の証明が必要です。' },
  { term: 'M Visa', category: 'travel', definition: '商業活動のための中国ビジネスビザ——貿易見本市、サプライヤー商談、契約交渉など。通常、中国企業の招聘状が必要。Mビザでの就労は禁止です。' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: '中国の2つの1週間の連休——春節（1～2月）と国慶節（10月1～7日）。国内旅行が急増し、観光地の混雑、ホテル価格のピーク、切符の完売が予想されます。数か月前に予約するか、避けましょう。' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: '中国のビザなしトランジット制度——2024年12月に全国規模で144時間から240時間へ延長——により、多くの国の国籍者が第三国へ乗り継ぐ際に最長10日間の滞在が可能です。対象国籍・港・条件は繰り返し拡大されています。これを前提に旅行計画を立てる前に、自国の国籍とルートに対する現行の適用範囲を必ず確認してください。' }, // {{VERIFY}} confirm current NIA policy scope and eligible ports at publish time
];

/* pt — machine-assisted definitions, pending native-speaker review. */
const GLOSSARY_PT: GlossaryTerm[] = [
  { term: 'CSC Scholarship', category: 'education', definition: 'A bolsa do governo chinês, administrada pelo China Scholarship Council. As concessões integrais incluem mensalidade, alojamento no campus, seguro de saúde e uma bolsa mensal; as parciais cobrem subconjuntos. Candidatura via Tipo A (canal governamental) ou Tipo B (diretamente a uma universidade designada pela CSC).' },
  { term: 'JW202 Form', category: 'visas', definition: 'O formulário de pedido de visto de estudos emitido por uma universidade chinesa a estudantes internacionais admitidos e autofinanciados e à maioria dos bolsistas de universidades, acompanhado da Admission Notice. Bolsistas do canal governamental (CSC Tipo A) geralmente recebem o formulário equivalente JW201 — use o formulário que a sua universidade emitir. Ambos ancoram o pedido de visto de estudante X1 numa embaixada ou consulado da China.' },
  { term: 'Admission Notice', category: 'education', definition: 'A carta de oferta formal de uma universidade chinesa confirmando sua vaga, programa e datas. Junto com o formulário JW202, ancora seu pedido de visto de estudante.' },
  { term: 'X1 Visa', category: 'visas', definition: 'O visto de estudante chinês para programas com mais de 180 dias. Emitido apenas para a entrada — o titular precisa convertê-lo em Permissão de Residência numa Secretaria de Segurança Pública local em até 30 dias após a chegada.' },
  { term: 'X2 Visa', category: 'visas', definition: 'O visto de estudante chinês para programas de 180 dias ou menos (cursos curtos, semestres de intercâmbio). Não pode ser convertido em permissão de residência e cobre uma ou duas entradas.' },
  { term: 'HSK (汉语水平考试)', zh: '汉语水平考试', category: 'exams', definition: 'O teste padronizado de proficiência em chinês da China (Hanyu Shuiping Kaoshi), níveis 1–6 no sistema 2.0 amplamente usado, com a nova norma 3.0 expandindo as faixas. O HSK 4 é o limiar comum para os estágios clínicos do MBBS; programas de graduação em chinês geralmente exigem HSK 5.' },
  { term: 'HSKK', category: 'exams', definition: 'A prova oral que acompanha o HSK, aplicada nos níveis iniciante, intermediário e avançado. Alguns programas em chinês pedem a HSKK junto com o HSK escrito.' },
  { term: 'MOE-listed University', category: 'education', definition: 'Uma universidade aprovada pelo Ministério da Educação da China para matricular estudantes internacionais — e, no caso do MBBS, para ministrar o curso em inglês. Se uma faculdade de medicina não está na lista anual do MOE, evite-a.' },
  { term: 'FMGE / NExT', category: 'education', definition: 'O Foreign Medical Graduate Examination da Índia — o exame de licenciamento que indianos devem passar depois de um MBBS no exterior para exercer na Índia. Está em transição para o National Exit Test (NExT). Verifique as regras atuais do NMC antes de se candidatar.' },
  { term: 'Residence Permit', category: 'visas', definition: 'O documento que substitui seu visto X1 após a chegada. Emitido pela administração local de Exit-Entry; exigido para a estadia legal de longo prazo, e necessário para abrir algumas contas bancárias e assinar contratos de aluguel.' },
  { term: 'Physical Examination Form', category: 'education', definition: 'O formulário padrão de exame de saúde chinês exigido para vistos X1 e permissões de residência. Deve ser preenchido numa clínica autorizada; candidatos à bolsa CSC devem usar a versão oficial enviada com o pacote de candidatura.' },
  { term: 'Intake (September / March)', category: 'education', definition: 'Os dois principais períodos de ingresso universitário na China. Setembro é o principal, com a maior oferta de programas; março é um ingresso menor oferecido por algumas universidades para programas selecionados.' },
  { term: 'Canton Fair', zh: '广交会', category: 'trade', definition: 'A Feira de Importação e Exportação da China em Guangzhou — a maior feira comercial do mundo, realizada em três fases a cada abril/maio e outubro/novembro. Fase 1: eletrônica e máquinas; Fase 2: bens de consumo e decoração; Fase 3: têxteis, vestuário e produtos médicos.' },
  { term: 'AQL Inspection', category: 'trade', definition: 'Amostragem por Nível de Qualidade Aceitável (AQL) — o método estatístico padrão da indústria para inspecionar lotes: uma amostra aleatória é retirada e os defeitos são julgados contra tolerâncias acordadas previamente (crítico/maior/menor) antes do embarque. À parte, as inspeções costumam ser agendadas a ~20% (produção inicial) e ~80% (quase concluída) — esses pontos de controle são uma escolha de fluxo de trabalho, não parte da norma AQL em si.' },
  { term: 'Bill of Lading (B/L)', category: 'trade', definition: 'O documento de título emitido pela transportadora para o frete marítimo. A condição de pagamento “70% contra cópia do B/L” significa que o saldo é pago quando o documento da naviera comprova que a mercadoria está a caminho.' },
  { term: 'TT (Telegraphic Transfer)', category: 'trade', definition: 'Transferência eletrônica — o canal de pagamento padrão no comércio com a China. Estruturada como entrada mais saldo (comumente 30/70) em vez de 100% adiantado, que expõe o comprador ao calote do fornecedor.' },
  { term: 'LC (Letter of Credit)', category: 'trade', definition: 'Um instrumento de pagamento garantido por banco: o banco do comprador paga o fornecedor quando as condições documentais do LC são atendidas. Comum no comércio empresarial consolidado; custa mais que o TT, mas protege ambas as partes.' },
  { term: 'HS Code', category: 'trade', definition: 'Código do Sistema Harmonizado — a classificação internacional de produtos que determina tarifas, restrições e licenciamento aduaneiro. Códigos HS errados são uma das principais causas de atrasos no desembaraço e de tarifas reavaliadas.' },
  { term: 'BIS Certification', category: 'trade', definition: 'O registro no Bureau of Indian Standards exigido para muitos eletrônicos e bens importados para a Índia (esquemas como o CRS para TI/eletrônica). A aprovação WPC se aplica a produtos sem fio. Ambos devem estar garantidos antes do embarque.' },
  { term: 'FCL / LCL', category: 'trade', definition: 'Full Container Load (sua mercadoria sozinha num contêiner de 20/40 pés) versus Less-than-Container-Load (sua mercadoria divide o espaço do contêiner). O LCL serve para pedidos de teste; o FCL vence no custo por unidade em escala.' },
  { term: 'L Visa', category: 'travel', definition: 'O visto de turista da China para visitas privadas. Concessão típica: 30–60 dias por entrada; algumas nacionalidades recebem validade maior ou versões multientrada. Exige roteiro, reservas e comprovação de continuação.' },
  { term: 'M Visa', category: 'travel', definition: 'O visto de negócios da China para atividades comerciais — feiras, reuniões com fornecedores, negociação de contratos. Normalmente precisa de carta-convite de uma empresa chinesa; trabalho é proibido com visto M.' },
  { term: 'Golden Week (黄金周)', zh: '黄金周', category: 'travel', definition: 'Os dois feriados nacionais de uma semana na China — Ano Novo Chinês (jan/fev) e Dia Nacional (1–7 de outubro). O turismo interno dispara; espere pontos turísticos lotados, preços de hotel no pico e trens esgotados. Reserve meses antes ou evite.' },
  { term: '240-hour Visa-free Transit', category: 'travel', definition: 'A política de trânsito sem visto da China — ampliada de 144 para 240 horas em todo o país em dezembro de 2024 — que permite a nacionais de muitos países entrar e ficar até 10 dias quando em trânsito para um terceiro país. As nacionalidades, portos e condições elegíveis se expandiram repetidamente; verifique o alcance atual da política para sua nacionalidade e rota antes de planejar uma viagem em cima dela.' }, // {{VERIFY}} confirm current NIA policy scope and eligible ports at publish time
];

